using System.Net.Http.Json;
using Microsoft.EntityFrameworkCore;
using PhoneStore.Core.Contracts;
internal sealed partial class QaSuite
{
    async Task Orders(){
        var variants=await Fixture(10,2);var request=await Cart(a,variants,2);OrderDto order=null!;
        await Check("UC03-010","Thông tin nhận không hợp lệ","400, không tạo đơn/giữ",async()=>{foreach(var r in new[]{request with{Recipient=""},request with{Phone="abc"},request with{Address="short"}})await Status(await a.Send("/api/orders",r),400);Assert((await Stock(variants[0].Id)).Reserved==0);});
        await Check("UC03-008","Không tin tổng/giá client","Giá giả409, total/paymentStatus overpost bị bỏ qua",async()=>{var forged=request with{Lines=request.Lines.Select(x=>x with{Price=1}).ToList()};await Status(await a.Send("/api/orders",forged),409);Assert((await Stock(variants[0].Id)).Reserved==0);});
        await Check("UC03-011","Tạo COD nhiều dòng","Pending/Unpaid, tổng đúng6 triệu",async()=>{order=await Place(a,request);Assert(order.Status=="CHO_XAC_NHAN"&&order.Payment=="CHUA_THU"&&order.Total==6000000m&&order.Lines.Count==2);});
        await Check("UC03-012","Dữ liệu đơn/chi tiết/thanh toán/giữ/log","Đủ tất cả bản ghi và giữ2 mỗi biến thể",async()=>{await using var db=Open();Assert(await db.Payments.CountAsync(x=>x.OrderId==order.Id)==1);Assert(await db.OrderLines.CountAsync(x=>x.OrderId==order.Id)==2);Assert(await db.Histories.CountAsync(x=>x.OrderId==order.Id)==1);Assert(await db.Movements.CountAsync(x=>x.OrderId==order.Id&&x.Kind=="GIU")==2);foreach(var v in variants)Assert((await Stock(v.Id)).Reserved==2);});
        await Check("UC03-014","Retry sau khi server đã commit","Cùng RequestKey trả cùng ID; không thêm giữ",async()=>{var repeated=await Place(a,request);Assert(repeated.Id==order.Id);Assert((await Stock(variants[0].Id)).Reserved==2);await Status(await b.Send("/api/orders",request),403);});
        await Check("UC03-015","Giỏ sau đặt hàng","Đã xóa dòng giỏ sau commit",async()=>Assert((await a.Read<CartDto>("/api/cart")).Lines.Count==0));
        await Check("UC04-001","Lịch sử theo chủ tài khoản","B không thấy đơn A",async()=>{var own=await a.Read<Page<OrderDto>>("/api/orders");var other=await b.Read<Page<OrderDto>>("/api/orders");Assert(own.Items.Any(x=>x.Id==order.Id)&&other.Items.All(x=>x.Id!=order.Id));});
        await Check("UC04-002","Chi tiết snapshot và tổng","Line.Total cộng đúng Order.Total",async()=>{var o=await a.Read<OrderDto>($"/api/orders/{order.Id}");Assert(o.Total==o.Lines.Sum(x=>x.Total)&&o.Recipient==request.Recipient&&o.Address==request.Address);});
        await Check("UC04-009","Sửa ID để xem/hủy đơn người khác","B nhận404; trạng thái A không đổi",async()=>{await Status(await b.Get($"/api/orders/{order.Id}"),404);await Status(await b.Send($"/api/orders/{order.Id}/cancel",new TransitionRequest(order.Version,Guid.NewGuid(),"QA")),404);Assert((await a.Read<OrderDto>($"/api/orders/{order.Id}")).Status=="CHO_XAC_NHAN");});
        await Check("UC09-003","Nhảy thẳng complete từ chờ","409, chưa thu COD",async()=>{await Status(await admin.Send($"/api/admin/orders/{order.Id}/complete",new TransitionRequest(order.Version,Guid.NewGuid())),409);Assert((await a.Read<OrderDto>($"/api/orders/{order.Id}")).Payment=="CHUA_THU");});
        await Check("UC09-002","Xác nhận đơn hợp lệ","Đã xác nhận, không đổi kho",async()=>{order=await Move(order.Id,"confirm");Assert(order.Status=="DA_XAC_NHAN"&&(await Stock(variants[0].Id)).OnHand==10);});
        await Check("UC04-005","Khách không hủy sau xác nhận","409; giữ không đổi",async()=>{await Status(await a.Send($"/api/orders/{order.Id}/cancel",new TransitionRequest(order.Version,Guid.NewGuid(),"QA")),409);Assert((await Stock(variants[0].Id)).Reserved==2);});
        await Check("UC09-004","Xuất giao cập nhật đồng thời thực/giữ","Thực8, giữ0 mỗi biến thể",async()=>{order=await Move(order.Id,"dispatch");foreach(var v in variants){var s=await Stock(v.Id);Assert(s.OnHand==8&&s.Reserved==0);}});
        await Check("UC09-005","Xuất giao lặp với version mới","409 và không trừ tồn lần2",async()=>{await Status(await admin.Send($"/api/admin/orders/{order.Id}/dispatch",new TransitionRequest(order.Version,Guid.NewGuid())),409);Assert((await Stock(variants[0].Id)).OnHand==8);});
        await Check("UC09-007","Shipping và thanh toán tách biệt","Đang giao nhưng CHUA_THU",async()=>{var o=await a.Read<OrderDto>($"/api/orders/{order.Id}");Assert(o.Status=="DANG_GIAO"&&o.Payment=="CHUA_THU");});
        await Check("UC09-006","Hoàn tất thu COD","HOAN_TAT/DA_THU; amount=6 triệu",async()=>{order=await Move(order.Id,"complete");await using var db=Open();var p=await db.Payments.FindAsync(order.Id);Assert(order.Status=="HOAN_TAT"&&order.Payment=="DA_THU"&&p!.Amount==6000000m&&p.ActorId==adminId);});
        await Check("UC09-011","Customer đọc trạng thái mới","Customer/Admin cùng trạng thái/total/version",async()=>{var o=await a.Read<OrderDto>($"/api/orders/{order.Id}");Assert(o.Status==order.Status&&o.Version==order.Version&&o.Total==order.Total);});
        await Check("UC09-012","Timeline có actor, giờ và trạng thái","4 bước đúng thứ tự",async()=>{var o=await a.Read<OrderDto>($"/api/orders/{order.Id}");Assert(o.History.Select(x=>x.To).SequenceEqual(new[]{"CHO_XAC_NHAN","DA_XAC_NHAN","DANG_GIAO","HOAN_TAT"}));Assert(o.History.All(x=>!string.IsNullOrWhiteSpace(x.Actor)));});
        await Check("UC10-008","Báo cáo không đếm trùng JOIN nhiều dòng","Revenue=6 triệu, count=1",async()=>{var r=await admin.Read<ReportResult>("/api/admin/reports?kind=revenue");Assert(r.Total==6000000m&&r.Count==1);});
        await Check("UC10-009","Bán chạy hai biến thể","Tổng4 sản phẩm, mỗi SKU2",async()=>{var r=await admin.Read<ReportResult>("/api/admin/reports?kind=bestsellers");Assert(r.Total==4&&r.Rows.Count==2&&r.Rows.All(x=>x.Value==2));});
        await Check("UC03-016","Thay giá/tên không đổi đơn cũ","Snapshot và tổng đơn giữ nguyên",async()=>{var p=await ProductFor(variants[0].Id);var i=Input(p);await Status(await admin.Send($"/api/admin/products/{p.Id}",i with{Name="Tên đã đổi",Variants=i.Variants.Select(x=>x with{Price=x.Price+5}).ToList()},HttpMethod.Put),200);var o=await a.Read<OrderDto>($"/api/orders/{order.Id}");Assert(o.Total==6000000m&&o.Lines[0].Price==1000000m&&o.Lines[0].Name!="Tên đã đổi");});
        var cancelV=await Fixture(2);var cancelRequest=await Cart(a,cancelV);var cancelOrder=await Place(a,cancelRequest);
        await Check("UC04-004","Hủy đơn chờ có lý do","DA_HUY, vẫn thực2",async()=>{await Status(await a.Send($"/api/orders/{cancelOrder.Id}/cancel",new TransitionRequest(cancelOrder.Version,Guid.NewGuid(),"Khách hủy QA")),200);var o=await a.Read<OrderDto>($"/api/orders/{cancelOrder.Id}");Assert(o.Status=="DA_HUY"&&(await Stock(cancelV[0].Id)).OnHand==2);});
        await Check("UC04-006","Hủy trả lượng giữ","Reserved=0 Available=2",async()=>{var s=await Stock(cancelV[0].Id);Assert(s.Reserved==0&&s.Available==2);});
        await Check("UC04-007","Hủy lặp không giải phóng thêm","409 và Available không vượt2",async()=>{var o=await a.Read<OrderDto>($"/api/orders/{cancelOrder.Id}");await Status(await a.Send($"/api/orders/{o.Id}/cancel",new TransitionRequest(o.Version,Guid.NewGuid(),"QA")),409);Assert((await Stock(cancelV[0].Id)).Available==2);});
        var failedV=await Fixture(1);var failed=await Place(a,await Cart(a,failedV));await Move(failed.Id,"confirm");await Move(failed.Id,"dispatch");
        await Check("UC09-008","Giao thất bại chưa nhập lại","Thực0/giữ0, chưa thu",async()=>{failed=await Move(failed.Id,"fail");var s=await Stock(failedV[0].Id);Assert(s.OnHand==0&&s.Reserved==0&&failed.Payment=="CHUA_THU");});
        await Check("UC09-009","Nhận hàng thực tế chỉ một lần","Thực1, lần lặp409",async()=>{failed=await Move(failed.Id,"return");Assert((await Stock(failedV[0].Id)).OnHand==1&&failed.ReturnReceived);await Status(await admin.Send($"/api/admin/orders/{failed.Id}/return",new TransitionRequest(failed.Version,Guid.NewGuid())),409);Assert((await Stock(failedV[0].Id)).OnHand==1);});
        await Check("UC10-001","Doanh thu chỉ hoàn tất đã thu","Vẫn đúng6 triệu sau đơn hủy/thất bại",async()=>Assert((await admin.Read<ReportResult>("/api/admin/reports?kind=revenue")).Total==6000000m));
        await Check("UC10-006","Báo cáo rỗng","Rows rỗng total0",async()=>{var r=await admin.Read<ReportResult>("/api/admin/reports?kind=revenue&from=2000-01-01&to=2000-01-02");Assert(r.Total==0&&r.Rows.Count==0);});
        await Check("UC10-005","Kỳ sai và ngày ngoài phạm vi","400, không500",async()=>{await Status(await admin.Get("/api/admin/reports?from=2026-12-01&to=2026-01-01"),400);await Status(await admin.Get("/api/admin/reports?from=0001-01-01"),400);await Status(await admin.Get("/api/admin/reports?to=9999-12-31"),400);await Status(await admin.Get("/api/admin/reports?from=not-a-date"),400);});
        await Check("UC10-004","Biên ngày UTC+7 đầu/cuối kỳ","17:00UTC thuộc ngày kế tiếp",async()=>{DateTime previous;await using(var db=Open()){previous=(await db.Orders.FindAsync(order.Id))!.CompletedAt!.Value;var utc=new DateTime(2020,1,1,17,0,0);await db.Database.ExecuteSqlInterpolatedAsync($"UPDATE DON_HANG SET CompletedAt={utc} WHERE Id={order.Id}");}try{Assert((await admin.Read<ReportResult>("/api/admin/reports?from=2020-01-01&to=2020-01-01")).Total==0);Assert((await admin.Read<ReportResult>("/api/admin/reports?from=2020-01-02&to=2020-01-02")).Total==6000000m);}finally{await using var db=Open();await db.Database.ExecuteSqlInterpolatedAsync($"UPDATE DON_HANG SET CompletedAt={previous} WHERE Id={order.Id}");}});
        await Check("UC03-009","Giá đổi/ngừng/hết tồn tại checkout","Không tạo đơn ở các nhánh lỗi",async()=>{var v=await Fixture(1);var req=await Cart(a,v);var p=await ProductFor(v[0].Id);var input=Input(p);await Status(await admin.Send($"/api/admin/products/{p.Id}",input with{Variants=input.Variants.Select(x=>x with{Price=x.Price+1}).ToList()},HttpMethod.Put),200);await Status(await a.Send("/api/orders",req),409);p=await ProductFor(v[0].Id);await Status(await admin.Send($"/api/admin/products/{p.Id}",Input(p) with{Active=false},HttpMethod.Put),200);await Status(await a.Send("/api/orders",req),400);Assert((await Stock(v[0].Id)).Reserved==0);});
        await Check("UC04-003","Lọc đơn theo trạng thái/ngày","Tất cả kết quả khớp lọc",async()=>{var list=await a.Read<Page<OrderDto>>("/api/orders?status=DA_HUY&from=2000-01-01&to=2099-01-01");Assert(list.Total>=1&&list.Items.All(x=>x.Status=="DA_HUY"));});
    }
}
